<script setup>definePageMeta({layout:'blank'});const config=useRuntimeConfig();const name=ref('');const email=ref('');const message=ref('');const pending=ref(false);const error=ref('');const success=ref('');async function requestAccess(){pending.value=true;error.value='';success.value='';try{await $fetch(`${config.public.apiBase}/api/public/contact`,{method:'POST',body:{firstName:name.value,lastName:'—',email:email.value,subject:'Pedido de acesso ao CMS',message:message.value||'Solicito acesso à área administrativa do GDCSS Castelões.'}});success.value='Pedido enviado. Um administrador poderá criar a tua conta no CMS.';name.value='';email.value='';message.value=''}catch(e){error.value=e?.data?.message||'Não foi possível enviar o pedido'}finally{pending.value=false}}</script><template><div class="flex items-center justify-center min-h-screen px-4"><div class="w-full max-w-md p-8 card-surface"><h1 class="text-fluid-2xl font-bold mb-3 text-center">Solicitar acesso</h1><p class="text-center text-neutral-600 mb-6">Por segurança, as contas do CMS são criadas por um administrador.</p><form @submit.prevent="requestAccess" class="space-y-4"><input v-model="name" required placeholder="Nome" class="w-full p-2 border rounded"><input v-model="email" required type="email" placeholder="Email" class="w-full p-2 border rounded"><textarea v-model="message" rows="4" placeholder="Motivo do pedido (opcional)" class="w-full p-2 border rounded"></textarea><p v-if="error" class="text-secondary-800">{{error}}</p><p v-if="success" class="text-primary-700">{{success}}</p><button class="w-full btn-club-green" :disabled="pending">{{pending?'A enviar…':'Enviar pedido'}}</button></form><NuxtLink to="/auth/login" class="block mt-4 text-center text-primary-700 hover:underline">Voltar ao login</NuxtLink></div></div></template>
